-columns:minmax(0,360px) minmax(0,1fr);gap:clamp(28px,4vw,72px);align-items:start}.md-doc-cover{display:block;border-radius:6px;overflow:hidden;box-shadow:0 22px 50px -18px rgba(0,0,0,.85),0 0 0 1px rgba(255,255,255,.1);transform:rotate(-2deg);transition:transform .4s var(--ease)}.md-doc:hover .md-doc-cover{transform:rotate(0) translateY(-2px)}.md-doc-cover img{display:block;width:100%;height:auto;background:#fff}.md-doc-k{margin:0 0 16px;font-size:clamp(19px,1.4vw,24px);font-weight:400;letter-spacing:-.02em;line-height:1.3;color:var(--t1)}.md-ol{margin:0;padding:0;list-style:none;counter-reset:md;display:grid;gap:12px}.md-ol li{counter-increment:md;position:relative;padding-left:40px;color:var(--t2);line-height:1.6}.md-ol li::before{content:counter(md);position:absolute;left:0;top:1px;width:26px;height:26px;border-radius:8px;display:grid;place-items:center;font-size:13px;font-weight:600;color:var(--t1);background:rgba(97,95,255,.18)}.md-ol b{color:var(--t1);font-weight:500}.md-doc-b{display:flex;flex-wrap:wrap;gap:12px;margin-top:26px}.md-doc-n{margin:16px 0 0;color:var(--t3);font-size:13px;line-height:1.5}.avt-kit{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:14px;margin-top:clamp(36px,4vw,60px)}.avt-kit-c{display:flex;flex-direction:column;gap:8px;padding:clamp(18px,1.6vw,24px)}.avt-kit-c>svg{width:24px;height:24px;color:var(--acc);margin-bottom:4px}.avt-kit-c b{font-weight:500;color:var(--t1);line-height:1.3}.avt-kit-c span{color:var(--t2);font-size:14.5px;line-height:1.5}.nb-author-wrap{display:grid;grid-template-columns:minmax(0,.75fr) minmax(0,1.25fr);gap:clamp(24px,3vw,56px);align-items:center}.nb-author{display:flex;gap:20px;align-items:center;padding:clamp(24px,2.4vw,36px)}.nb-avatar{flex:none;display:block;width:112px;height:112px;border-radius:50%;object-fit:cover;background:#18181b;border:1px solid rgba(124,134,255,.4)}.nb-author p{margin:0}.nb-author-name{font-size:clamp(20px,1.5vw,26px);color:var(--t1);letter-spacing:-.02em;margin-bottom:4px!important}.nb-author-role{color:var(--t2);margin-bottom:4px!important}.nb-author-date{color:var(--t3);font-size:14px}.nb-author-note{color:var(--t3);font-size:13px;margin-top:6px!important}.nb-author-text{color:#c4c4cc;font-size:clamp(16px,1.08vw,19px);line-height:1.65;margin:0;max-width:760px}.cta-contacts .avt-mail{font-size:clamp(16px,1.1vw,19px);color:var(--t2);text-decoration:underline;text-decoration-color:var(--acc);text-underline-offset:4px}.cta-contacts .avt-mail:hover{color:var(--t1)}@media (max-width:1180px){.avt-tr,.avt-stats{grid-template-columns:repeat(2,minmax(0,1fr))}.avt-kit{grid-template-columns:repeat(3,minmax(0,1fr))}.avt-zmap{grid-template-columns:minmax(0,1fr)}.avt-zlist{grid-template-columns:repeat(2,minmax(0,1fr))}}@media (max-width:860px){.avt-def,.avt-two,.avt-spec,.nb-author-wrap{grid-template-columns:minmax(0,1fr)}.avt-def{align-items:start}.avt-steps{grid-template-columns:repeat(2,minmax(0,1fr))}.avt-hero .avt-price-line{order:3;margin:14px 0 0;font-size:14px}.md-doc{grid-template-columns:minmax(0,1fr)}.md-doc-cover{max-width:300px;margin:0 auto}.avt-freq td:first-child,.avt-freq td:last-child,.avt-docs td:first-child{min-width:0}}@media (max-width:600px){.avt-tr,.avt-stats,.avt-zlist,.avt-steps{grid-template-columns:minmax(0,1fr)}.avt-kit{grid-template-columns:repeat(2,minmax(0,1fr))}.avt-plan{padding:10px}.avt-plan .bdg{transform:scale(1.5);transform-box:fill-box;transform-origin:center}.md-doc-b .btn{width:100%;justify-content:center}.avt-cold{flex-direction:column;gap:12px}.nb-author{align-items:flex-start}.nb-avatar{width:80px;height:80px}}@media (max-width:420px){.avt-kit{grid-template-columns:minmax(0,1fr)}}@media (max-width:380px){.avt-prices tr{grid-template-columns:minmax(0,1fr)}.avt-prices td.d-price{grid-column:1;grid-row:2;text-align:left}.avt-prices td:nth-child(2){grid-row:3}}
</style>
<script type="application/ld+json">{"@context": "https://schema.org", "@graph": [{"@type": "BreadcrumbList", "itemListElement": [{"@type": "ListItem", "position": 1, "name": "Главная", "item": "https://xn----itbbsflddbfpfdodg9d0f.xn--p1ai/"}, {"@type": "ListItem", "position": 2, "name": "Дезинфекция для организаций", "item": "https://xn----itbbsflddbfpfdodg9d0f.xn--p1ai/dezinfektsiya/"}, {"@type": "ListItem", "position": 3, "name": "Дезинфекция автотранспорта", "item": "https://xn----itbbsflddbfpfdodg9d0f.xn--p1ai/dezinfektsiya/avtotransport/"}]}, {"@type": "WebPage", "@id": "https://xn----itbbsflddbfpfdodg9d0f.xn--p1ai/dezinfektsiya/avtotransport/#webpage", "url": "https://xn----itbbsflddbfpfdodg9d0f.xn--p1ai/dezinfektsiya/avtotransport/", "name": "Дезинфекция автотранспорта и санобработка кузова в Москве — от 900 ₽", "description": "Дезинфекция грузового транспорта, автобусов и такси в Москве и МО: санобработка кузова рефрижератора за 15 минут, акт на каждую машину. От 900 ₽.", "inLanguage": "ru", "dateModified": "2026-11-20", "about": {"@id": "https://xn----itbbsflddbfpfdodg9d0f.xn--p1ai/dezinfektsiya/avtotransport/#service"}, "author": {"@type": "Person", "name": "Марианна Семерина", "jobTitle": "Санитарный врач"}, "primaryImageOfPage": {"@type": "ImageObject", "url": "https://xn----itbbsflddbfpfdodg9d0f.xn--p1ai/img/avto-hero.webp", "caption": "Специалист в комбинезоне, полумаске и перчатках обрабатывает дезинфицирующим раствором стенку кузова рефрижератора с открытыми задними дверями"}, "hasPart": [{"@id": "https://xn----itbbsflddbfpfdodg9d0f.xn--p1ai/dezinfektsiya/avtotransport/#akt-obrazets"}, {"@id": "https://xn----itbbsflddbfpfdodg9d0f.xn--p1ai/dezinfektsiya/avtotransport/#akt-blank"}], "publisher": {"@type": "Organization", "name": "ПЕСТКОНТРОЛЬ Центр"}}, {"@type": "Service", "@id": "https://xn----itbbsflddbfpfdodg9d0f.xn--p1ai/dezinfektsiya/avtotransport/#service", "name": "Дезинфекция автотранспорта", "serviceType": "Дезинфекция и санитарная обработка транспортных средств", "url": "https://xn----itbbsflddbfpfdodg9d0f.xn--p1ai/dezinfektsiya/avtotransport/", "description": "Дезинфекция кузовов фургонов, изотерм и рефрижераторов, фур и полуприцепов, салонов автобусов, такси и каршеринга на стоянке заказчика в Москве и Московской области: 15 минут на машину, акт с госномером, журнал и наклейка в кабину. Мусоровозы и транспорт медицинских отходов — по запросу.", "areaServed": [{"@type": "City", "name": "Москва"}, {"@type": "AdministrativeArea", "name": "Московская область"}], "audience": {"@type": "BusinessAudience", "name": "Юридические лица и ИП"}, "provider": {"@type": "Organization", "@id": "https://xn----itbbsflddbfpfdodg9d0f.xn--p1ai/#org", "name": "ПЕСТКОНТРОЛЬ Центр", "legalName": "ООО «Центр дезинфекционных услуг»", "url": "https://xn----itbbsflddbfpfdodg9d0f.xn--p1ai/", "telephone": "+7 495 104-35-70", "email": "b2b@pestcontrol-center.ru"}, "offers": {"@type": "AggregateOffer", "priceCurrency": "RUB", "lowPrice": "900", "description": "Дезинфекция автотранспорта от 900 ₽ за машину; расчёт по списку машин — 0 ₽; удаление запаха — по расчёту; ночные и выходные окна без наценки"}}, {"@type": "DigitalDocument", "@id": "https://xn----itbbsflddbfpfdodg9d0f.xn--p1ai/dezinfektsiya/avtotransport/#akt-obrazets", "name": "Образец акта дезинфекции автотранспорта", "url": "https://xn----itbbsflddbfpfdodg9d0f.xn--p1ai/dezinfektsiya/avtotransport/obrazets-akta-dezinfektsii-avtotransporta.pdf", "encodingFormat": "application/pdf", "inLanguage": "ru"}, {"@type": "DigitalDocument", "@id": "https://xn----itbbsflddbfpfdodg9d0f.xn--p1ai/dezinfektsiya/avtotransport/#akt-blank", "name": "Бланк акта санобработки транспортного средства", "url": "https://xn----itbbsflddbfpfdodg9d0f.xn--p1ai/dezinfektsiya/avtotransport/blank-akta-dezinfektsii-avtotransporta.pdf", "encodingFormat": "application/pdf", "inLanguage": "ru"}, {"@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": "Нужен ли санитарный паспорт на машину для перевозки продуктов?", "acceptedAnswer": {"@type": "Answer", "text": "Нет. Требование отменено с 21 октября 2011 года Федеральным законом от 19.07.2011 № 248-ФЗ, Роспотребнадзор подтвердил это письмом от 31.10.2011 № 01/13750-1-32 (подборка КонсультантПлюс). Санобработку машины подтверждают договор с исполнителем и акт на каждую обработку."}}, {"@type": "Question", "name": "Должны ли грузовые отделения транспортных средств и контейнеры подвергаться регулярной очистке, мойке, дезинфекции?", "acceptedAnswer": {"@type": "Answer", "text": "Да. Это прямое требование технического регламента: регулярно и с такой периодичностью, чтобы кузов и контейнеры не стали источником загрязнения продукции. Внутренние поверхности моют водой, которая соответствует требованиям к питьевой (ТР ТС 021/2011, ст. 17, п. 6)."}}, {"@type": "Question", "name": "Как часто проводится санитарная обработка транспорта для перевозки пищевых продуктов?", "acceptedAnswer": {"@type": "Answer", "text": "Для мяса — после каждой перевозки (ТР ТС 034/2013, п. 101). Для остальной продукции частоту устанавливает перевозчик в программе производственного контроля. Ориентир из методических рекомендаций Роспотребнадзора — мойка ежедневно, дезинфекция ежемесячно (МР 3.5.0372-25, п. 10.3)."}}, {"@type": "Question", "name": "Сколько действует санобработка грузового транспорта?", "acceptedAnswer": {"@type": "Answer", "text": "Срока действия у акта санитарной обработки автомобиля нет: он подтверждает, что машину обработали в конкретный день. Актуальность определяет ваш график — при ежемесячной дезинфекции нужен акт текущего месяца, для мяса — акт после каждой перевозки. Дату следующей обработки пишем в акте и на наклейке в кабине."}}, {"@type": "Question", "name": "Какой должна быть конструкция грузовых отделений транспортных средств и контейнеров?", "acceptedAnswer": {"@type": "Answer", "text": "Такой, чтобы защищать продукцию от загрязнения, грызунов и насекомых и позволять очистку, мойку и дезинфекцию; внутренняя поверхность — из моющихся и нетоксичных материалов (ТР ТС 021/2011, ст. 17, пп. 3, 5). Надорванный уплотнитель, щели в обшивке и забитые трапы отмечаем в акте как замечание."}}, {"@type": "Question", "name": "Какие средства применяются для дезинфекции автотранспорта?", "acceptedAnswer": {"@type": "Answer", "text": "Только зарегистрированные средства III–IV класса опасности по инструкции к ним (СанПиН 3.3686-21, п. 131), разрешённые для транспорта и поверхностей, которые контактируют с пищевой продукцией. При плесени — средство с фунгицидным действием. Название, номер госрегистрации и концентрацию указываем в акте."}}, {"@type": "Question", "name": "Можно ли дезинфицировать машины своими силами?", "acceptedAnswer": {"@type": "Answer", "text": "Можно: правила допускают работу подготовленного персонала самой организации (СанПиН 3.3686-21, п. 131). Понадобятся средства III–IV класса опасности, обученные сотрудники и учёт обработок. Лицензия нужна тем, кто оказывает такие услуги другим (постановление Правительства РФ от 20.03.2024 № 337). Наша лицензия — № Л064-00111-77/01942445, её можно проверить в реестре Роспотребнадзора."}}, {"@type": "Question", "name": "Сколько длится обработка и когда можно загружать машину?", "acceptedAnswer": {"@type": "Answer", "text": "15 минут работы на машину. Затем выдержка по инструкции средства, смыв, если инструкция его требует, и проветривание. Время до загрузки называем заранее, чтобы рейс не сдвинулся."}}, {"@type": "Question", "name": "Можно ли дезинфицировать рефрижератор при минусовой температуре?", "acceptedAnswer": {"@type": "Answer", "text": "Промёрзший кузов без отогрева не обрабатываем: на стене ниже нуля раствор замерзает и не действует. Установку выключают заранее, наледь убирают, кузов прогревается до плюсовой температуры — затем мойка и дезинфекция. Средство с режимом для минусовых температур применяем, только если такой режим записан в его зарегистрированной инструкции."}}, {"@type": "Question", "name": "Как убрать запах из кузова после рыбы и мяса?", "acceptedAnswer": {"@type": "Answer", "text": "Найти и убрать источник: остатки продукции в стыках, трапах и уплотнителях. Затем мойка, дезинфекция и обработка средством от запахов с проветриванием. Если запах впитался в уплотнитель или пол, без замены детали он вернётся. Удаление запаха — отдельная услуга, цена по расчёту."}}, {"@type": "Question", "name": "Какие медицинские документы должен иметь экспедитор при перевозке пищевых продуктов?", "acceptedAnswer": {"@type": "Answer", "text": "Личную медицинскую книжку с отметками о предварительном и периодических медосмотрах: их проходят все, кто контактирует с продукцией при перевозке, включая водителя-экспедитора и грузчиков (ТР ТС 021/2011, ст. 17, п. 10). Нужна и санитарная одежда. Санитарной книжки у самой машины законодательство не предусматривает."}}, {"@type": "Question", "name": "Есть ли особые условия для мусоровозов и транспорта медицинских отходов?", "acceptedAnswer": {"@type": "Answer", "text": "Да. Мусоровозы и ассенизационные машины моют с дезинфекцией не реже 1 раза в 10 суток (СанПиН 2.1.3684-21, пп. 16, 26). Транспорт медицинских отходов — только специализированный: для класса А мытьё, дезинфекция и дезинсекция не реже 1 раза в неделю, для классов Б и В — после каждой перевозки (пп. 203, 204, 207). Такие машины обрабатываем по запросу."}}]}]}</script>
